effect.script:
function animate(env,el,p) {
    let groups = [];
    groups.push(0);
    el.shaderGroups = groups;
    return el;
}

effect.shader:

vec4 newLayer( vec4 a, vec4 b) { return a * (1. - b.a) + b;  }
mat2 rot2m(float a){ float s = sin(a); float c = cos(a); return mat2(c, -s, s, c); }
vec2 l2s( vec2 v ) { return (vec4(v,0.,1.)*acLayerToScreen).xy; }
#define fragCoord gl_FragCoord.xy

//////////////////////////
    const int M = 1;

    const mat3 rgb2ycbcr = mat3(
        0.299, -0.168736, 0.5,
        0.587, -0.331264, -0.418688,
        0.114, 0.5, -0.081312
    );

    vec3 rgb2gray = vec3(0.299, 0.587, 0.114);

    const mat3 ycbcr2rgb = mat3(
        1.0, 1.0, 1.0,
        0.0, -0.344136, 1.772,
        1.402, -0.714136, 0.0
    );
//////////////////////////
    void main() {
    if( acPass == 0 ) { gl_FragColor = texture2DCv(inputImg.texture, acScreenNorm.st); } else if( acPass==1 ) {
    vec4 texColor = texture2DCv(inputImg.texture,acScreenNorm);
    vec4 texColorX = vec4(0.0,0.0,0.0,1.0) * texColor.a;

    vec2 image_size = getTexSize(inputImg.size);
    vec2 iResolution = vec2(acScreenSize.x, acScreenSize.y);
    vec2 iMouse = vec2(0.5, 0.5);

    /////////////////////////

	vec4 fragColor;

        vec2 step = vec2(1.)/getTexSize(inputImg.size) * radius;
        vec4 srcColor = texture2DCv(inputImg.texture, acScreenNorm.st);
        highp vec3 color = vec3(0);

        float p1 = dot(rgb2gray, (texture2DCv(inputImg.texture, acScreenNorm.st + step * vec2(-1, -1)).rgb));
        float p2 = dot(rgb2gray, (texture2DCv(inputImg.texture, acScreenNorm.st + step * vec2(0, -1)).rgb));
        float p3 = dot(rgb2gray, (texture2DCv(inputImg.texture, acScreenNorm.st + step * vec2(1, -1)).rgb));
        float p4 = dot(rgb2gray, (texture2DCv(inputImg.texture, acScreenNorm.st + step * vec2(-1, 0)).rgb));
        float p5 = dot(rgb2gray, (srcColor.rgb));
        float p6 = dot(rgb2gray, (texture2DCv(inputImg.texture, acScreenNorm.st + step * vec2(1, 0)).rgb));
        float p7 = dot(rgb2gray, (texture2DCv(inputImg.texture, acScreenNorm.st + step * vec2(-1, 1)).rgb));
        float p8 = dot(rgb2gray, (texture2DCv(inputImg.texture, acScreenNorm.st + step * vec2(0, 1)).rgb));
        float p9 = dot(rgb2gray, (texture2DCv(inputImg.texture, acScreenNorm.st + step * vec2(1, 1)).rgb));

        float f1 = 2.0 * p5 - p4 - p6;
        float f2 = 2.0 * p5 - p2 - p8;
        float f3 = 2.0 * p5 - p3 - p7;
        float f4 = 2.0 * p5 - p1 - p9;

        float maxf = max(max(max(abs(f1), abs(f2)), abs(f3)), abs(f4));
        vec3 ycbcr = rgb2ycbcr * srcColor.rgb;

        float f;
        if (TYPE==0) {
            f = f1; }
        else if (TYPE==1) {
            f = f2; }
        else if (TYPE==2) {
            f = f3; }
        else if (TYPE==3) {
            f = f4; }

        color = ycbcr2rgb * ((ycbcr + vec3(sharpness * f * 0.5, 0, 0)));
        fragColor = vec4(color, srcColor.a);

	gl_FragColor = mix(texColor, fragColor, alpha) * texColor.a;
      }
    }
